* { box-sizing: border-box; }
.products { display: grid; gap: 1rem;
  grid-template-columns: repeat(auto-fit,minmax(min(100%,220px),1fr)); }
.card { min-width:0; padding:1rem; border:1px solid #aaa;
  border-radius:8px; transition:transform .2s; }
.actions { display:flex; flex-wrap:wrap; gap:.5rem; }
button { min-height:44px; }
button:focus-visible { outline:3px solid #125fa0; }
@media (hover:hover) { .card:hover { transform:translateY(-3px); } }
@media (prefers-reduced-motion:reduce) {
  .card { transition:none; } .card:hover { transform:none; }
}
